import * as T from './three.module.js';
const $=s=>document.querySelector(s), modal=$('#final');
const stops=[new T.Vector3(-7,0,3),new T.Vector3(-2,0,-1),new T.Vector3(4,0,-3),new T.Vector3(8,0,2)];
let index=0,unlocked=0,moving=false,arrival=false,party=0;
const chapters=[['01 · BẾN KHỞI HÀNH','Chiếc thuyền đưa bạn đến một quần đảo lơ lửng giữa trời. Mảnh ghép đầu tiên đang ở Vườn ý tưởng, nơi những điều mới mẻ bắt đầu từ một câu hỏi nhỏ.','Đến Vườn ý tưởng →'],['02 · MẢNH GHÉP SÁNG TẠO ✦','Bạn tìm thấy ngôi sao Sáng tạo! Cảm ơn những góc nhìn mới và những ý tưởng giúp công việc tốt hơn mỗi ngày. Phía xa, một ngọn đèn đang dẫn đường…','Đến Ngọn hải đăng →'],['03 · MẢNH GHÉP ĐỒNG HÀNH ☀','Bạn tìm thấy ánh sáng Đồng hành! Có những ngày nhiều việc, nhưng một lời hỗ trợ đúng lúc khiến mọi thứ nhẹ hơn. Mảnh ghép cuối cùng đang chờ ở quảng trường.','Đến Quảng trường →'],['04 · MẢNH GHÉP TÍCH CỰC ♡','Bạn tìm thấy trái tim Tích cực! Một nụ cười, một lời động viên — những điều nhỏ làm nên một nơi làm việc đáng mến. Ba mảnh ghép đã đủ. Món quà này dành cho bạn.','Mở món quà 20/10 ✨']];
try{
const scene=new T.Scene();scene.background=new T.Color('#172d36');scene.fog=new T.FogExp2('#172d36',.018);
const camera=new T.PerspectiveCamera(42,innerWidth/innerHeight,.1,180),renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;$('#world').append(renderer.domElement);
scene.add(new T.HemisphereLight(0xccefff,0x334b51,2.4));const sun=new T.DirectionalLight(0xffd5a4,4);sun.position.set(-8,18,10);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-22,right:22,top:20,bottom:-20});scene.add(sun);
const mats={grass:mat(0x789d83),rock:mat(0x536f70),edge:mat(0x3a555e),wood:mat(0xa67a56),gold:mat(0xffcc78,.4),pink:mat(0xe7a6a0),green:mat(0x456e62),cream:mat(0xf5e5bd),dark:mat(0x304c54)};
function mat(c,r=.85){return new T.MeshStandardMaterial({color:c,roughness:r});}
function mesh(g,m,p,parent=scene){const o=new T.Mesh(g,m);o.position.set(...p);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
function box(x,y,z,m,p,parent){return mesh(new T.BoxGeometry(x,y,z),m,p,parent);}
function cylinder(r1,r2,h,m,p,parent,n=8){return mesh(new T.CylinderGeometry(r1,r2,h,n),m,p,parent);}
function sphere(r,m,p,parent){return mesh(new T.IcosahedronGeometry(r,1),m,p,parent);}
function textSprite(txt,size=1.5){const c=document.createElement('canvas');c.width=1024;c.height=256;const ctx=c.getContext('2d');ctx.fillStyle='#fff0c9';ctx.font='600 80px sans-serif';ctx.textAlign='center';ctx.fillText(txt,512,150);const s=new T.Sprite(new T.SpriteMaterial({map:new T.CanvasTexture(c),depthTest:false,transparent:true}));s.scale.set(size*4,size,1);return s;}
const islands=[],clickables=[],gifts=[];
stops.forEach((p,i)=>{const g=new T.Group();g.position.copy(p);scene.add(g);islands.push(g);cylinder(2.65,2.35,.5,mats.grass,[0,-.25,0],g,10);cylinder(2.3,.4,2.5,mats.rock,[0,-1.7,0],g,7);cylinder(1.4,.2,1.6,mats.edge,[.35,-3,0],g,5);const pad=cylinder(1.1,1.1,.05,mats.cream,[0,.04,0],g,32);pad.userData.stop=i;clickables.push(pad);for(let j=0;j<7;j++){const a=j/7*Math.PI*2;const rock=sphere(.15,mats.cream,[Math.cos(a)*2.15,.1,Math.sin(a)*2.15],g);rock.scale.y=.5;}const label=textSprite(['BẾN KHỞI HÀNH','VƯỜN Ý TƯỞNG','NGỌN HẢI ĐĂNG','QUẢNG TRƯỜNG 20/10'][i],.52);label.position.set(0,3.5,0);g.add(label);});
function tree(g,x,z,s=1){cylinder(.09,.14,1.2*s,mats.wood,[x,.6*s,z],g);cylinder(0,.6*s,1.3*s,mats.green,[x,1.45*s,z],g,6);cylinder(0,.45*s,1*s,mats.grass,[x,2*s,z],g,6);}
tree(islands[0],-1.5,-.8);tree(islands[0],1.2,-1.2,.7);tree(islands[1],-1.4,-1,.9);tree(islands[1],1.5,.6,.7);tree(islands[2],-1.5,.7,.6);tree(islands[3],1.3,-1,.8);
// A tiny office departure dock and paper boat.
for(let i=0;i<5;i++)box(.34,.12,1.6,mats.wood,[-.7+i*.35,.1,2.1],islands[0]);const boat=mesh(new T.ConeGeometry(.6,.5,3),mats.cream,[0,.4,2.4],islands[0]);boat.rotation.z=Math.PI;box(.04,1,.04,mats.wood,[0,.9,2.4],islands[0]);const sail=mesh(new T.ConeGeometry(.4,.65,3),mats.pink,[.15,1.1,2.4],islands[0]);sail.rotation.y=Math.PI/2;
// Idea garden: flowers around a little worktable.
box(1.1,.12,.65,mats.wood,[0,.7,-.8],islands[1]);for(const x of [-.4,.4])box(.08,.7,.08,mats.wood,[x,.35,-.8],islands[1]);box(.5,.03,.35,mats.cream,[0,.79,-.8],islands[1]);for(let i=0;i<13;i++){const a=i*2.4,r=1.2+(i%3)*.3,x=Math.cos(a)*r,z=Math.sin(a)*r;cylinder(.025,.025,.4,mats.green,[x,.2,z],islands[1]);for(let j=0;j<5;j++){const b=j/5*6.28;sphere(.12,mats.pink,[x+Math.cos(b)*.12,.45,z+Math.sin(b)*.12],islands[1]);}sphere(.08,mats.gold,[x,.49,z],islands[1]);}
// Lighthouse with a rotating warm beacon.
cylinder(.5,.7,2.3,mats.cream,[.35,1.15,-.7],islands[2]);cylinder(.52,.58,.25,mats.pink,[.35,1.7,-.7],islands[2]);cylinder(.65,.65,.15,mats.dark,[.35,2.35,-.7],islands[2]);cylinder(.38,.38,.55,mats.gold,[.35,2.7,-.7],islands[2]);cylinder(0,.65,.45,mats.dark,[.35,3.15,-.7],islands[2]);const beacon=new T.PointLight(0xffcc77,6,12);beacon.position.set(4.35,2.8,-3.7);scene.add(beacon);
// Final plaza, gift and celebration arch.
for(const x of [-1.2,1.2])cylinder(.07,.07,2.3,mats.gold,[x,1.15,-.5],islands[3]);const arch=mesh(new T.TorusGeometry(1.2,.07,8,32,Math.PI),mats.gold,[0,2.3,-.5],islands[3]);const title=textSprite('20 / 10',.5);title.position.set(0,2.6,-.45);islands[3].add(title);box(.9,.7,.9,mats.pink,[0,.4,0],islands[3]);box(1,.15,1,mats.cream,[0,.82,0],islands[3]);box(.13,.8,.93,mats.gold,[0,.43,0],islands[3]);box(.93,.8,.13,mats.gold,[0,.43,0],islands[3]);for(const x of [-.2,.2]){const b=mesh(new T.TorusGeometry(.21,.045,7,24),mats.gold,[x,1,.0],islands[3]);b.rotation.y=.4;b.scale.y=.65;}
// Connecting bridges: only the next step becomes available.
for(let i=0;i<3;i++){const a=stops[i],b=stops[i+1],d=b.clone().sub(a),len=d.length(),dir=d.clone().normalize();for(let j=0;j<12;j++){const q=a.clone().addScaledVector(dir,2+j*(len-4)/11);const plank=box(.65,.12,.25,mats.wood,[q.x,-.02,q.z]);plank.rotation.y=-Math.atan2(dir.z,dir.x)+Math.PI/2;} }
// Collectible symbols hovering over the destinations.
for(let i=1;i<4;i++){const g=new T.Group();g.position.copy(stops[i]).add(new T.Vector3(0,1.6,.5));scene.add(g);const core=i===1?mesh(new T.OctahedronGeometry(.27),mats.gold,[0,0,0],g):i===2?sphere(.25,mats.gold,[0,0,0],g):sphere(.27,mats.pink,[0,0,0],g);const ring=mesh(new T.TorusGeometry(.43,.015,6,40),mats.gold,[0,0,0],g);ring.rotation.x=Math.PI/2;gifts.push(g);}
// Small explorer character carrying a satchel.
const player=new T.Group();scene.add(player);cylinder(.2,.25,.55,mats.pink,[0,.57,0],player);sphere(.22,mats.cream,[0,1.03,0],player);cylinder(.31,.31,.07,mats.gold,[0,1.21,0],player,16);cylinder(.22,.25,.18,mats.gold,[0,1.31,0],player,16);box(.24,.28,.15,mats.wood,[0,.63,.24],player);const legs=[];for(const x of [-.12,.12]){const l=box(.12,.3,.14,mats.dark,[x,.17,0],player);legs.push(l);}player.position.copy(stops[0]).add(new T.Vector3(0,0,.7));
// Clouds and warm drifting stars.
for(let i=0;i<18;i++){const g=new T.Group();g.position.set((Math.random()-.5)*48,-4-Math.random()*6,(Math.random()-.5)*36);for(let j=0;j<4;j++){const cloud=sphere(1.2,mat(0x6d8587),[j*1.2,Math.random()*.3,0],g);cloud.scale.set(1,.35,.7);}scene.add(g);}
const particles=new T.BufferGeometry(),pos=new Float32Array(450);for(let i=0;i<450;i++)pos[i]=(Math.random()-.5)*45;particles.setAttribute('position',new T.BufferAttribute(pos,3));const stars=new T.Points(particles,new T.PointsMaterial({color:0xffd59e,size:.055,transparent:true,opacity:.8}));scene.add(stars);
let yaw=.5,pitch=.64,zoom=25,drag=false,lastX=0,lastY=0,dragged=0;const focus=new T.Vector3(1,0,0),targetFocus=new T.Vector3(1,0,0);const pointer=new T.Vector2(),ray=new T.Raycaster();
renderer.domElement.addEventListener('pointerdown',e=>{drag=true;lastX=e.clientX;lastY=e.clientY;dragged=0;renderer.domElement.setPointerCapture(e.pointerId);});renderer.domElement.addEventListener('pointermove',e=>{if(drag){const dx=e.clientX-lastX,dy=e.clientY-lastY;yaw-=dx*.005;pitch=T.MathUtils.clamp(pitch+dy*.003,.35,1.1);dragged+=Math.abs(dx)+Math.abs(dy);lastX=e.clientX;lastY=e.clientY;}});renderer.domElement.addEventListener('pointerup',e=>{drag=false;if(dragged<8){pointer.set(e.clientX/innerWidth*2-1,1-e.clientY/innerHeight*2);ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects(clickables)[0];if(hit)go(hit.object.userData.stop);}});renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();zoom=T.MathUtils.clamp(zoom+e.deltaY*.015,15,40);},{passive:false});
function updateUI(){const c=chapters[index];$('#chapter').textContent=c[0];$('#narrative').textContent=c[1];$('#next').textContent=c[2];$('#next').disabled=false;$('#count').textContent=`${Math.min(unlocked,3)} / 3 mảnh ghép đã tìm thấy`;document.querySelectorAll('.progress span').forEach((s,i)=>s.classList.toggle('done',i<unlocked));document.querySelectorAll('[data-stop]').forEach((b,i)=>{b.disabled=i>Math.min(unlocked+1,3);b.classList.toggle('active',i===index);});}
let destination=player.position.clone();function go(i){if(moving||i>unlocked+1||i===index&&arrival)return;index=i;moving=true;arrival=true;destination=stops[i].clone().add(new T.Vector3(0,0,.7));targetFocus.copy(stops[i]).multiplyScalar(.6);$('#chapter').textContent='EN ROUTE · ĐANG KHÁM PHÁ';$('#narrative').textContent='Qua chiếc cầu nhỏ, đến một điều tuyệt vời khác. Mỗi bước chân là một lời cảm ơn gửi đến bạn.';$('#next').textContent='Đang trên đường…';$('#next').disabled=true;}
$('#next').onclick=()=>{if(!arrival){arrival=true;updateUI();return;}if(index<3)go(index+1);else{modal.showModal();party=1;}};document.querySelectorAll('[data-stop]').forEach(b=>b.onclick=()=>go(Number(b.dataset.stop)));$('.close').onclick=()=>modal.close();$('#celebrate').onclick=()=>{party=1;$('#celebrate').textContent='Chúc mọi điều ước thành hiện thực ✦';};$('#replay').onclick=()=>{modal.close();index=0;unlocked=0;arrival=false;moving=false;player.position.copy(stops[0]).add(new T.Vector3(0,0,.7));targetFocus.set(1,0,0);$('#next').textContent='Bắt đầu chuyến đi →';$('#chapter').textContent='LỜI MỞ ĐẦU · MỘT NGÀY KHÁC MỌI NGÀY';$('#narrative').textContent='Sáng nay, một chiếc thuyền giấy ghé văn phòng. Bên trong là tấm bản đồ: “Hãy tìm ba điều làm nên một đội ngũ tuyệt vời.” Bạn sẵn sàng lên đường chưa?';$('#count').textContent='0 / 3 mảnh ghép đã tìm thấy';document.querySelectorAll('.progress span').forEach(s=>s.classList.remove('done'));gifts.forEach(g=>g.visible=true);document.querySelectorAll('[data-stop]').forEach((b,i)=>{b.disabled=i>0;b.classList.toggle('active',i===0);});};
addEventListener('keydown',e=>{if(modal.open)return;if(['ArrowRight','ArrowUp','w','d'].includes(e.key)){e.preventDefault();if(!arrival){arrival=true;updateUI();}else if(index<3)go(index+1);}if(['ArrowLeft','ArrowDown','a','s'].includes(e.key)&&index>0){e.preventDefault();go(index-1);}});
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);zoom=innerWidth<700?32:25;}addEventListener('resize',resize);resize();$('#loading').remove();let prev=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
renderer.setAnimationLoop(ms=>{const t=ms*.001,dt=Math.min((ms-prev)/1000,.05);prev=ms;if(moving){const diff=destination.clone().sub(player.position);if(diff.length()<.09){player.position.copy(destination);moving=false;unlocked=Math.max(unlocked,index);if(index>0){gifts[index-1].visible=false;party=.4;}updateUI();}else{player.position.addScaledVector(diff.normalize(),Math.min(dt*3,diff.length()));player.rotation.y=Math.atan2(diff.x,diff.z);legs.forEach((l,i)=>l.rotation.x=Math.sin(t*12+i*Math.PI)*.5);player.position.y=Math.abs(Math.sin(t*10))*.07;}}else legs.forEach(l=>l.rotation.x=0);focus.lerp(targetFocus,.025);const horizontal=zoom*Math.cos(pitch);camera.position.set(focus.x+Math.sin(yaw)*horizontal,focus.y+zoom*Math.sin(pitch),focus.z+Math.cos(yaw)*horizontal);camera.lookAt(focus.x,focus.y,focus.z);gifts.forEach((g,i)=>{if(!reduced){g.rotation.y=t*.7;g.position.y=1.6+Math.sin(t*2+i)*.12;}});if(!reduced){stars.rotation.y=t*.015;boat.position.y=.4+Math.sin(t*2)*.06;if(party>0){stars.rotation.z+=dt*party;party=Math.max(0,party-dt*.12);}}renderer.render(scene,camera);});
}catch(e){$('#loading').innerHTML='<div class="error">Trình duyệt chưa hỗ trợ WebGL.<br>Hãy thử Chrome hoặc Safari mới để khám phá thế giới 3D.<br><br>Chúc các đồng nghiệp nữ một ngày 20/10 thật vui, luôn hạnh phúc và được trân trọng!</div>';console.error(e);}
